('FI101','Kde nájsť pomoc a podporu','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/apua_ja_tukea.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Stres a odolnosť']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Jednostranový prehľad osôb a služieb, na ktoré sa mladý človek môže obrátiť v škole, komunite alebo online. Menované služby sú fínske: pri použití na Slovensku treba kontakty nahradiť miestnymi. Slúži na pomenovanie možností podpory, nie ako slovenský adresár.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI102','Moje vzťahové zručnosti','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/ihmissuhdetaituri.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Vzťahy a triedna klíma']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Cvičenie vedie mladého človeka k pomenovaniu vlastností, ktoré si váži na priateľoch, a k odhadu vlastných komunikačných zručností na škále. Podporuje rozhovor o vzťahoch, empatii a rozvíjaní zručností bez známkovania.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI103','Na škále priateľstva','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/kaveruuden_janalla.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Vzťahy a triedna klíma']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Pracovný list s otázkami o dôvere, dôvernosti, konfliktoch a priateľstve. Mladý človek vyznačuje svoje postoje na škále medzi súhlasom a nesúhlasom a môže sa o odpovediach porozprávať s dospelým.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI104','Denník vďačnosti','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/kiitollisuuspaivakirja.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Všeobecná prevencia a wellbeing']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Počas siedmich dní si mladý človek zapíše alebo odfotí jednu drobnú vec, za ktorú je vďačný. Na konci týždňa sa vracia k záznamom a pomenúva myšlienky a pocity. Je to dobrovoľné cvičenie všímavosti, nie liečba depresie.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI105','Kto som?','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/kuka_mina_olen.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Všeobecná prevencia a wellbeing']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Jednoduchý list na sebapoznanie cez životné roly, záujmy, hodnoty, jedinečnosť a vlastnosti. Pomáha mladým pomenovať, ako sa vnímajú, bez potreby zdieľať osobné odpovede s celou skupinou.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI106','Nájdi svoje hodnoty','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/loyda_arvosi.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Všeobecná prevencia a wellbeing']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Cvičenie porovnáva osobné postoje a životné hodnoty. Pomáha uvedomiť si, na čom človeku záleží a ako hodnoty vplývajú na rozhodnutia, priateľstvá a budúce plány. Neexistuje jedna správna odpoveď.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI107','Ruka duševného zdravia – osobné cvičenie','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/mielenterveyden_kasi.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Stres a odolnosť']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Fínsky pracovný list prepája päť oblastí každodenného života: jedlo, vzťahy, pohyb, spánok a zmysluplný voľný čas. Pomáha premýšľať, ktorú oblasť by mladý človek chcel podporiť. Ide o reflexiu návykov, nie diagnostický nástroj.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI108','Moja myšlienková mapa','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/mielikartta_tehtava.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Všeobecná prevencia a wellbeing']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Vizuálna myšlienková mapa na otázky o identite, vzťahoch, hodnotách a životnej pohode, doplnená drobnými aktivitami. Niektoré úlohy možno vynechať, ak sú nepríjemné; obsahuje fínske kontakty na podporu.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI109','Dokážem to – zvládanie prekážok','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/mina_selvian.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Stres a odolnosť']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Samostatný fínsky list zo zbierky Hyvän mielen treenivihko venovaný zvládaniu ťažších situácií. Je vhodný ako podnet na rozhovor o podpore a vlastných skúsenostiach; konkrétne zadanie je potrebné čítať z originálneho PDF.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI110','Čo je na mne dobré','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/minussa_on_hyvaa.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Všeobecná prevencia a wellbeing']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Sebapoznávacie cvičenie, v ktorom si mladý človek zapisuje svoje silné stránky a pozitívne vlastnosti podľa písmen vlastného mena. Cieľom je posilniť všímavosť voči vlastným zdrojom, nie porovnávať sa s ostatnými.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI111','Kde v tele cítim emócie?','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/missa_tunne_tuntuu.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Emócie a správanie']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Pracovný list na pozorovanie telesných prejavov emócií. Môže pomôcť pomenovať rozdiel medzi pocitmi v tele a tým, čo človek urobí. Vhodný aj ako pomôcka pri sprevádzanom rozhovore.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI112','Moje bezpečné miesto','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/oma_mielipaikkani.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Stres a odolnosť']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Fínsky list zo zošita o mieste, ktoré si človek spája s pokojom alebo dobrým pocitom. Používateľ môže skúmať, čo mu navodzuje bezpečie. Nepoužívať ako náhradu odbornej podpory pri traume.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI113','S hlavou v oblakoch – moje ciele','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/paa_pilvissa.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Všeobecná prevencia a wellbeing']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Zapisovanie malých a väčších cieľov na tento mesiac, budúci rok a dospelosť. Cvičenie pomáha premýšľať o budúcnosti bez tlaku, že každý plán sa musí nevyhnutne splniť.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI114','Kvapky na zamyslenie','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/pohdinnan_pisarat.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Všeobecná prevencia a wellbeing']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Súbor krátkych otázok o sebavedomí, úspechoch, neistotách a náročných situáciách. Mladý človek odpovedá písomne alebo kresbou; otázky môžu poslúžiť aj pri rozhovore s bezpečným dospelým.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI115','Zastavme sa – chvíľa pokoja','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/pysahdytaan.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Stres a odolnosť']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Krátka aktivita na sústredenie a odpočinok: odložiť telefón, vyfarbiť obrázok a potom opísať, aké bolo sústrediť sa iba na jednu činnosť. Nie je to univerzálna terapia, ale nenáročná forma pozorovania svojho prežívania.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI116','Smer vpred – iný pohľad na ťažkosť','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/Suunta-eteenpain.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Stres a odolnosť']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Úloha pracuje s nepríjemnou situáciou a hľadaním realistickejšieho alebo povzbudivejšieho spôsobu, ako sa na ňu pozrieť. Neznamená popieranie problémov; pri závažnom trápení je dôležitá podpora dospelého.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI117','Moje budúce ja','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/tulevaisuuden_mina.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Všeobecná prevencia a wellbeing']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Kresba a otázky o budúcom živote: čo by som chcel robiť, naučiť sa, kde žiť a s kým tráviť čas. Je to tvorivá aktivita na spoznávanie prianí a nádejí, nie plán kariéry s pevnými záväzkami.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI118','Môj teplomer emócií','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/tunnemittarini.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Emócie a správanie']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Týždenné zaznamenávanie pocitov a ich intenzity. Cieľom je všímať si, ktoré emócie sa opakujú; pri dlhodobom smútku alebo výraznom trápení materiál odporúča porozprávať sa s dôveryhodným dospelým.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI119','Ako pracovať s emóciami','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/tunteet_haltuun.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Emócie a správanie']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Samostatný fínsky pracovný list zo súboru mentálnych zručností pre mladých. Materiál je určený na rozpoznanie a zvládanie emócií; podrobný postup je vo fínskom origináli.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI120','Prečo sú emócie dôležité','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/tunteiden_merkitys.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Emócie a správanie']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Krátke cvičenie z fínskeho zošita o význame emócií v každodennom živote. Ponúka príležitosť rozlišovať medzi cítením, myslením a konaním bez označovania emócií za zlé alebo dobré.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI121','Bezpečie a pomoc','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/turvaa_ja_tukea.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Stres a odolnosť']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Samostatný list zo zbierky na tému bezpečia a podpory. Vhodný pre tínedžerov pri mapovaní dôveryhodných ľudí; obsah je po fínsky, preto môže byť potrebná pomoc dospelého.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI122','Moja záchranná sieť','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/turvaverkkoni.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Vzťahy a triedna klíma']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Vizuálne mapovanie blízkych a ďalších ľudí, na ktorých sa mladý človek môže obrátiť. Pomáha odlíšiť rôzne formy podpory a rozmýšľať, komu zavolať pri náročnom dni.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI123','Vlajočky mojich zdrojov','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/voimavarojen_viirit.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Stres a odolnosť']::text[],'Pracovný list PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Mladý človek do pripravených vlajočiek vypisuje činnosti, prostredia a ľudí, pri ktorých sa cíti lepšie. Cvičenie vytvára osobnú zbierku drobných zdrojov psychickej pohody.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI124','Hyvän mielen treenivihko – celý pracovný zošit','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/hyvan_mielen_treenivihko.pdf',ARRAY['Dieťa alebo mladý človek']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Stres a odolnosť']::text[],'Pracovný zošit PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Kompletný 32-stranový fínsky pracovný zošit pre mladých, ktorý možno vypĺňať individuálne alebo s pracovníkom s mládežou. Venuje sa spánku, každodenným návykom, vzťahom, silným stránkam, emóciám a zvládaniu náročných situácií. Jednotlivé cvičenia sú v knižnici aj samostatne.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI125','Hyvän mielen – príručka pre facilitátora','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/hyvan_mielen_ohjaajan_opas.pdf',ARRAY['Učiteľ alebo škola','Odborník']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Škola a adaptácia']::text[],'Metodická príručka PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Fínska 40-stranová metodika pre prácu s mládežou. Obsahuje krátke aktivity približne na 15–30 minút a otázky na spoločnú reflexiu. Pomáha viesť cvičenia bezpečne a bez tlaku na odhaľovanie osobných informácií.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI126','Hyvän mielen – ročný plán duševnej pohody','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/Hyvan-mielen-vuosikello.pdf',ARRAY['Učiteľ alebo škola','Odborník']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Škola a adaptácia']::text[],'Metodika PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Metodický ročný kalendár pre tím pracovníkov s mládežou. Pomáha počas školského roka systematicky zaradiť témy duševnej pohody do bežnej práce. Je to organizačná pomôcka, nie klinická intervencia.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI127','Hyvän mielen – prázdna šablóna ročného kalendára','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/Vuosikello_pohja.pdf',ARRAY['Učiteľ alebo škola','Odborník']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Škola a adaptácia']::text[],'Šablóna PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Jednostranová šablóna na vlastné plánovanie aktivít podporujúcich duševnú pohodu v skupine mladých. Používa sa spolu s ročným plánom MIELI.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI128','Hyvän mielen – vystrihovacie doplnky ku kalendáru','MIELI Mental Health Finland','https://mieli.fi/wp-content/uploads/2021/07/Vuosikello_leikattavat_lisaosat.pdf',ARRAY['Učiteľ alebo škola','Odborník']::text[],ARRAY['10–12 rokov','13–15 rokov','16–18 rokov']::text[],ARRAY['Škola a adaptácia']::text[],'Pracovné pomôcky PDF','Voľne dostupné PDF','Bezplatné','fi','FI','fi',ARRAY['fi']::text[],'Doplnkové vytlačiteľné diely k ročnému kalendáru MIELI, pripravené na spoločné plánovanie a tvorivú prácu. Jazyk originálu je fínsky.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
('FI129','Being Together – spolupráca a priateľstvo malých detí','MIELI Mental Health Finland','https://mieli.fi/en/materials/being-together/',ARRAY['Učiteľ alebo škola','Rodič alebo blízky']::text[],ARRAY['0–5 rokov','6–9 rokov']::text[],ARRAY['Vzťahy a triedna klíma']::text[],'Plagát PDF','Voľne dostupné PDF','Bezplatné','en','FI','en',ARRAY['en']::text[],'Anglický plagát MIELI pre predškolské deti znázorňuje základné sociálne zručnosti a učenie spolužitiu. Dospelí ho môžu využiť pri rozhovore o rešpekte, vzájomnej pomoci a bezpečných vzťahoch.','Hyvän mielen treenivihko – jednotlivé listy',true,'Zahraničný odborný zdroj',current_date,'Zdroj MIELI – prepojenie na dokument vydavateľa, bez miestnej kópie PDF.'),
